text:
.panel-viewcontainer {
  overflow: hidden;
  flex-shrink: 0;
  min-inline-size: 0;
  min-block-size: 0;
  max-block-size: 100%;

  &[panelopen] {
    transition-property: height;
    transition-timing-function: var(--animation-easing-function);
    transition-duration: var(--panelui-subview-transition-duration);
    will-change: height;
  }
